/** The Android snapshot bridge unions transaction IDs, never balances. */
public final class CloudMerge {
    private static final List<String> WALLET=Arrays.asList("coins","hintCoupons","xp");
    private static final List<String> STATS=Arrays.asList("wins","time","moves","perfect","attempts");
    private static final List<String> THEMES=Arrays.asList("gold","ice","fire","shadow","emerald","ruby","ocean","amethyst","neon");
    private static final List<String> STATE=Arrays.asList("shopActiveTheme","v9_theme","v9_quest","wheelState","achievementPeaks","seenLessons","fastest","minMoves","dailyRecords","dailyLastReward","activeGame","dailyActiveGame");
    private CloudMerge() {}
    private static String join(List<String> parts){StringBuilder s=new StringBuilder();for(String p:parts){if(s.length()>0)s.append(',');s.append(p);}return s.toString();}
    private static boolean validAccount(String s){if(s==null||s.isEmpty()||s.length()>256)return false;for(int i=0;i<s.length();i++)if(s.charAt(i)<32||s.charAt(i)==127)return false;return true;}
    private static boolean safe(String s){return s!=null&&s.matches("[a-zA-Z0-9_:.-]{1,220}")&&!Arrays.asList("__proto__","constructor","prototype").contains(s);}
    private static long number(Object v){try{double n=Double.parseDouble(String.valueOf(v));return Double.isFinite(n)?(long)Math.min(1e12,Math.max(0,Math.floor(n))):0;}catch(Exception e){return 0;}}
    private static boolean integer(Object v){if(!(v instanceof Number))return false;double n=((Number)v).doubleValue();return Double.isFinite(n)&&Math.floor(n)==n&&Math.abs(n)<=9007199254740991d;}
    private static boolean truth(Object v){return v!=null&&v!=JSONObject.NULL&&!Boolean.FALSE.equals(v)&&!"".equals(v)&&!"0".equals(String.valueOf(v));}
    private static Object copy(Object v)throws Exception{if(v instanceof JSONObject)return new JSONObject(v.toString());if(v instanceof JSONArray)return new JSONArray(v.toString());return v==null?JSONObject.NULL:v;}
    private static TreeSet<String> keys(JSONObject... values){TreeSet<String> out=new TreeSet<>();for(JSONObject v:values)if(v!=null)for(Iterator<String> i=v.keys();i.hasNext();)out.add(i.next());return out;}
    public static String canonical(Object v)throws Exception{if(v==null||v==JSONObject.NULL)return "null";if(v instanceof JSONObject){JSONObject o=(JSONObject)v;List<String> parts=new ArrayList<>();for(String k:keys(o))parts.add(JSONObject.quote(k)+":"+canonical(o.opt(k)));return "{"+join(parts)+"}";}if(v instanceof JSONArray){JSONArray a=(JSONArray)v;List<String> parts=new ArrayList<>();for(int i=0;i<a.length();i++)parts.add(canonical(a.opt(i)));return "["+join(parts)+"]";}return JSONObject.valueToString(v);}
    private static JSONObject maxMap(JSONObject a,JSONObject b)throws Exception{JSONObject r=new JSONObject();for(String k:keys(a,b))if(safe(k))r.put(k,Math.max(number(a==null?null:a.opt(k)),number(b==null?null:b.opt(k))));return r;}
    private static JSONObject counter(JSONObject a,JSONObject b)throws Exception{JSONObject r=maxMap(a,b),days=new JSONObject();r.remove("days");JSONObject x=a==null?null:a.optJSONObject("days"),y=b==null?null:b.optJSONObject("days");for(String date:keys(x,y))if(date.matches("\\d{4}-\\d{2}-\\d{2}"))days.put(date,maxMap(x==null?null:x.optJSONObject(date),y==null?null:y.optJSONObject(date)));r.put("days",days);return r;}
    private static JSONObject trueMap(JSONObject a,JSONObject b)throws Exception{JSONObject r=new JSONObject();for(String k:keys(a,b))if(safe(k)&&(a!=null&&Boolean.TRUE.equals(a.opt(k))||b!=null&&Boolean.TRUE.equals(b.opt(k))))r.put(k,true);return r;}
    private static JSONObject minMap(JSONObject a,JSONObject b)throws Exception{JSONObject r=new JSONObject();for(JSONObject o:new JSONObject[]{a,b})if(o!=null)for(String k:keys(o))if(k.matches("[1-9][0-9]{0,2}")&&Integer.parseInt(k)<=300){Object value=o.opt(k);double n;try{n=Double.parseDouble(String.valueOf(value));}catch(Exception e){continue;}if(!Double.isFinite(n)||n<0)continue;long v=number(value);r.put(k,r.has(k)?Math.min(number(r.opt(k)),v):v);}return r;}
    private static JSONObject better(JSONObject a,JSONObject b,String field,String secondary)throws Exception{if(a==null)return b==null?null:(JSONObject)copy(b);if(b==null)return (JSONObject)copy(a);for(String k:new String[]{field,secondary}){long x=number(a.opt(k)),y=number(b.opt(k));if(x!=y)return (JSONObject)copy(x<y?a:b);}boolean x=truth(a.opt("assisted")),y=truth(b.opt("assisted"));if(x!=y)return (JSONObject)copy(x?b:a);return (JSONObject)copy(canonical(a).compareTo(canonical(b))<0?a:b);}
    private static long sum(JSONObject o){long n=0;for(String k:keys(o))n+=number(o.opt(k));return n;}
    private static JSONObject daily(JSONObject a,JSONObject b)throws Exception{JSONObject out=new JSONObject();for(String date:keys(a,b)){if(!date.matches("\\d{4}-\\d{2}-\\d{2}"))continue;JSONObject x=a==null?null:a.optJSONObject(date),y=b==null?null:b.optJSONObject(date);if(x==null)x=new JSONObject();if(y==null)y=new JSONObject();JSONObject runs=trueMap(x.optJSONObject("runs"),y.optJSONObject("runs")),r=new JSONObject();JSONObject attemptActors=maxMap(x.optJSONObject("attemptActors"),y.optJSONObject("attemptActors"));long base=Math.max(x.has("attemptBase")?number(x.opt("attemptBase")):Math.max(0,number(x.opt("attempts"))-sum(x.optJSONObject("attemptActors"))),y.has("attemptBase")?number(y.opt("attemptBase")):Math.max(0,number(y.opt("attempts"))-sum(y.optJSONObject("attemptActors"))));r.put("attemptBase",base);r.put("attemptActors",attemptActors);r.put("attempts",base+sum(attemptActors));r.put("wins",Math.max(runs.length(),Math.max(number(x.opt("wins")),number(y.opt("wins")))));r.put("stars",Math.min(3,Math.max(number(x.opt("stars")),number(y.opt("stars")))));r.put("runs",runs);JSONObject moves=better(x.optJSONObject("bestMoves"),y.optJSONObject("bestMoves"),"moves","seconds"),time=better(x.optJSONObject("bestTime"),y.optJSONObject("bestTime"),"seconds","moves");if(moves!=null)r.put("bestMoves",moves);if(time!=null)r.put("bestTime",time);Object last=canonical(x.opt("last")).compareTo(canonical(y.opt("last")))>0?x.opt("last"):y.opt("last");if(last!=null&&last!=JSONObject.NULL)r.put("last",copy(last));out.put(date,r);}return out;}
    private static int stamp(JSONObject a,JSONObject b)throws Exception{int n=Long.compare(number(a.opt("n")),number(b.opt("n")));if(n!=0)return n;n=a.optString("d").compareTo(b.optString("d"));return n!=0?n:canonical(a.opt("v")).compareTo(canonical(b.opt("v")));}
    private static JSONObject state(String key,JSONObject a,JSONObject b)throws Exception{if(a==null)return (JSONObject)copy(b);if(b==null)return (JSONObject)copy(a);JSONObject win=stamp(a,b)>=0?a:b;Object v=copy(win.opt("v"));if(key.equals("achievementPeaks"))v=maxMap(a.optJSONObject("v"),b.optJSONObject("v"));else if(key.equals("seenLessons"))v=trueMap(a.optJSONObject("v"),b.optJSONObject("v"));else if(key.equals("fastest")||key.equals("minMoves"))v=minMap(a.optJSONObject("v"),b.optJSONObject("v"));else if(key.equals("dailyRecords"))v=daily(a.optJSONObject("v"),b.optJSONObject("v"));else if(key.equals("v9_quest")){JSONObject x=a.optJSONObject("v"),y=b.optJSONObject("v");String dx=x==null?"":x.optString("date"),dy=y==null?"":y.optString("date");if(!dx.equals(dy))v=copy(dx.compareTo(dy)>0?x:y);if(v instanceof JSONObject)((JSONObject)v).put("claimed",new JSONObject());}else if(key.equals("wheelState")){JSONObject x=a.optJSONObject("v"),y=b.optJSONObject("v");String dx=x==null?"":x.optString("date"),dy=y==null?"":y.optString("date");if(dx.equals(dy)&&v instanceof JSONObject){JSONObject w=(JSONObject)v;w.put("freeUsed",truth(x==null?null:x.opt("freeUsed"))||truth(y==null?null:y.opt("freeUsed")));w.put("bonusUsed",truth(x==null?null:x.opt("bonusUsed"))||truth(y==null?null:y.opt("bonusUsed")));w.put("adCount",Math.min(3,Math.max(number(x==null?null:x.opt("adCount")),number(y==null?null:y.opt("adCount")))));}else v=copy(dx.compareTo(dy)>0?x:y);}JSONObject r=new JSONObject();r.put("n",Math.max(number(a.opt("n")),number(b.opt("n"))));r.put("d",win.optString("d"));r.put("v",v);return r;}
    private static boolean validRoot(JSONObject r){return r!=null&&safe(r.optString("id"))&&r.optJSONObject("wallet")!=null&&r.optJSONObject("claims")!=null&&r.optJSONObject("stats")!=null&&r.optJSONArray("owned")!=null;}
    private static JSONObject normalize(JSONObject f)throws Exception{if(f==null||f.optInt("schema")!=1||!validAccount(f.optString("account")))throw new IllegalArgumentException("Bulut kayıt şeması geçersiz");JSONObject out=new JSONObject();out.put("schema",1);out.put("account",f.getString("account"));for(String k:new String[]{"root","proposal"})if(validRoot(f.optJSONObject(k)))out.put(k,copy(f.getJSONObject(k)));JSONObject ops=new JSONObject(),source=f.optJSONObject("ops");for(String id:keys(source)){JSONObject o=source.optJSONObject(id);if(!safe(id)||o==null||!safe(o.optString("d"))||!integer(o.opt("n"))||((Number)o.opt("n")).longValue()<=0)throw new IllegalArgumentException("Bulut işlemi geçersiz");JSONObject p=new JSONObject();p.put("n",((Number)o.opt("n")).longValue());p.put("d",o.optString("d"));for(String k:WALLET){Object amount=o.has(k)?o.opt(k):Integer.valueOf(0);if(!integer(amount))throw new IllegalArgumentException("Bulut tutarı geçersiz");double value=((Number)amount).doubleValue();if(!Double.isFinite(value)||Math.floor(value)!=value||Math.abs(value)>1e9||k.equals("xp")&&value<0)throw new IllegalArgumentException("Bulut tutarı geçersiz");p.put(k,(long)value);}if(o.has("theme")){if(!THEMES.contains(o.optString("theme")))throw new IllegalArgumentException("Bulut teması geçersiz");p.put("theme",o.getString("theme"));}ops.put(id,p);}out.put("ops",ops);JSONObject counters=new JSONObject(),cs=f.optJSONObject("counters");for(String id:keys(cs))if(safe(id)&&cs.optJSONObject(id)!=null){JSONObject c=new JSONObject();for(String k:STATS)c.put(k,number(cs.getJSONObject(id).opt(k)));c.put("days",counter(cs.getJSONObject(id),null).getJSONObject("days"));counters.put(id,c);}out.put("counters",counters);JSONObject states=new JSONObject(),ss=f.optJSONObject("state");for(String key:keys(ss)){JSONObject v=ss.optJSONObject(key);if(STATE.contains(key)&&v!=null&&safe(v.optString("d"))&&integer(v.opt("n"))&&((Number)v.opt("n")).longValue()>=0&&v.has("v")){JSONObject n=new JSONObject();n.put("n",((Number)v.opt("n")).longValue());n.put("d",v.optString("d"));n.put("v",copy(v.opt("v")));states.put(key,n);}}out.put("state",states);return out;}
    public static JSONObject merge(JSONObject a,JSONObject b)throws Exception{if(a==null&&b==null)return null;if(a==null)a=new JSONObject().put("schema",1).put("account",b.optString("account"));if(b==null)b=new JSONObject().put("schema",1).put("account",a.optString("account"));a=normalize(a);b=normalize(b);if(a.has("root")&&!b.has("root")&&b.has("proposal")&&!a.getJSONObject("root").getString("id").equals(b.getJSONObject("proposal").getString("id")))b.put("state",new JSONObject());if(b.has("root")&&!a.has("root")&&a.has("proposal")&&!b.getJSONObject("root").getString("id").equals(a.getJSONObject("proposal").getString("id")))a.put("state",new JSONObject());if(!a.getString("account").equals(b.getString("account")))throw new IllegalArgumentException("Başka hesaba ait bulut kaydı reddedildi");JSONObject r=new JSONObject().put("schema",1).put("account",a.getString("account"));List<JSONObject> roots=new ArrayList<>();for(JSONObject f:new JSONObject[]{a,b})if(f.has("root"))roots.add(f.getJSONObject("root"));if(roots.isEmpty())for(JSONObject f:new JSONObject[]{a,b})if(f.has("proposal"))roots.add(f.getJSONObject("proposal"));if(!roots.isEmpty()){Collections.sort(roots,(x,y)->{int c=x.optString("id").compareTo(y.optString("id"));if(c!=0)return c;try{return canonical(x).compareTo(canonical(y));}catch(Exception e){throw new IllegalArgumentException(e);}});r.put("root",copy(roots.get(0)));}JSONObject ops=new JSONObject(),oa=a.getJSONObject("ops"),ob=b.getJSONObject("ops");for(String id:keys(oa,ob)){JSONObject x=oa.optJSONObject(id),y=ob.optJSONObject(id),chosen;if(x==null)chosen=y;else if(y==null)chosen=x;else{int c=x.getString("d").compareTo(y.getString("d"));chosen=c<0?x:c>0?y:canonical(x).compareTo(canonical(y))<=0?x:y;}ops.put(id,copy(chosen));}r.put("ops",ops);JSONObject counters=new JSONObject(),ca=a.getJSONObject("counters"),cb=b.getJSONObject("counters");for(String id:keys(ca,cb))counters.put(id,counter(ca.optJSONObject(id),cb.optJSONObject(id)));r.put("counters",counters);JSONObject states=new JSONObject(),sa=a.getJSONObject("state"),sb=b.getJSONObject("state");for(String key:keys(sa,sb))states.put(key,state(key,sa.optJSONObject(key),sb.optJSONObject(key)));r.put("state",states);return r;}
}
